INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3636906, 508059, 72317, '<td valign="top">This isn''t an awful image, but considering the other entries and the effort they made, I''m going to score it a tad bit lower just because I can see you didn''t put a whole lot of effort into the challenge. Holler at me if you like, but it won''t make your photo any more exciting. I am impressed however at your collection of books. It definitely recalls the works of Dr. Suess.</td>', 'This isn''t an awful image, but considering the other entries and the effort they made, I''m going to score it a tad bit lower just because I can see you didn''t put a whole lot of effort into the challenge. Holler at me if you like, but it won''t make your photo any more exciting. I am impressed however at your collection of books. It definitely recalls the works of Dr. Suess.', '2007-05-10 12:34:38.000000', NULL, 1),
(3636911, 507152, 72317, '<td valign="top">The background color isn''t my favorite, and I don''t understand the placement of the stuffie, and the ham isn''t green.<br/>Otherwise, it''s fine. It kindof looks like the camera was really close to that piece of ham. It looks blurry.</td>', 'The background color isn''t my favorite, and I don''t understand the placement of the stuffie, and the ham isn''t green.Otherwise, it''s fine. It kindof looks like the camera was really close to that piece of ham. It looks blurry.', '2007-05-10 12:36:10.000000', NULL, 1),
(3636912, 508119, 72317, '<td valign="top">Awwh.<br/>=)</td>', 'Awwh.=)', '2007-05-10 12:36:25.000000', NULL, 1),
(3636914, 508120, 7743, '<td valign="top">I like the composition however feel it would have more wow if the reflection wasn''t so dark.</td>', 'I like the composition however feel it would have more wow if the reflection wasn''t so dark.', '2007-05-10 12:37:39.000000', NULL, 1),
(3636915, 508046, 66398, '<td valign="top">What is that thing. The shape of it and what it looks like is great for the challenge but what is it actually? Nice studio shot. Lighting, clarity, color, and composition all look good and it meets challenge.</td>', 'What is that thing. The shape of it and what it looks like is great for the challenge but what is it actually? Nice studio shot. Lighting, clarity, color, and composition all look good and it meets challenge.', '2007-05-10 12:37:45.000000', NULL, 1),
(3636920, 507369, 72317, '<td valign="top">Oh gosh. I sure hope there were no teeth knocked out during this.<br/>Or by the look of the blond girl, other body parts..<br/>Hehe.<br/>Great idea.<br/>One thing I might suggest though that others may not:<br/>The background/area of shooting and the clothing choices.<br/>Though in the book, I do believe the hopping took place in the home in casual dress, for shooting a picture that is to be entered in a challenge, perhaps you might want to try a more professional approach with it.<br/>Just a suggestion. Just trying to help.</td>', 'Oh gosh. I sure hope there were no teeth knocked out during this.Or by the look of the blond girl, other body parts..Hehe.Great idea.One thing I might suggest though that others may not:The background/area of shooting and the clothing choices.Though in the book, I do believe the hopping took place in the home in casual dress, for shooting a picture that is to be entered in a challenge, perhaps you might want to try a more professional approach with it.Just a suggestion. Just trying to help.', '2007-05-10 12:39:05.000000', NULL, 1),
(3636926, 508146, 72317, '<td valign="top">The bright areas around the bowl make me wonder if there was alot of patch-tool usage. The picture is very bright and clear as well. The upper left corner in the background is a little noisy or something, but not horridly.<br/>Overall this is a great image, and I wish you good luck.<br/>=)</td>', 'The bright areas around the bowl make me wonder if there was alot of patch-tool usage. The picture is very bright and clear as well. The upper left corner in the background is a little noisy or something, but not horridly.Overall this is a great image, and I wish you good luck.=)', '2007-05-10 12:42:25.000000', NULL, 1),
(3636928, 507153, 72317, '<td valign="top">I do not understand the picture, but perhaps its from a book I haven''t read. Otherwise, it''s alright I suppose.</td>', 'I do not understand the picture, but perhaps its from a book I haven''t read. Otherwise, it''s alright I suppose.', '2007-05-10 12:43:20.000000', NULL, 1),
(3636936, 508074, 72317, '<td valign="top">I see random spots of blur here and there.<br/>A little messy looking with the blurry spots..<br/>The image is a bit cluttered looking, but it meets the challenge and its very colorful.</td>', 'I see random spots of blur here and there.A little messy looking with the blurry spots..The image is a bit cluttered looking, but it meets the challenge and its very colorful.', '2007-05-10 12:44:57.000000', NULL, 1),
(3636938, 507842, 72317, '<td valign="top">It has this unrealistic over-edited feel.<br/>My personal opinion, of course.<br/>But, that was my favorite book when I was little. <br/>=P</td>', 'It has this unrealistic over-edited feel.My personal opinion, of course.But, that was my favorite book when I was little. =P', '2007-05-10 12:45:54.000000', NULL, 1),
(3636942, 508136, 66398, '<td valign="top">It might have been a little better if you had selected the boy and made only him green instead of the whole photo. Or even selected the background and altered its color to not have the green cast. It would have made the boy "pop" just a little better. Still great execution of the idea and fits the challenge well. I like the way the jars are arranged so that you see all six jars.</td>', 'It might have been a little better if you had selected the boy and made only him green instead of the whole photo. Or even selected the background and altered its color to not have the green cast. It would have made the boy "pop" just a little better. Still great execution of the idea and fits the challenge well. I like the way the jars are arranged so that you see all six jars.', '2007-05-10 12:46:33.000000', NULL, 1),
