(3637496, 507237, 55621, '<td valign="top">Erotic Seuss! That''s a new one for the books, literally. 7</td>', 'Erotic Seuss! That''s a new one for the books, literally. 7', '2007-05-10 16:18:14.000000', NULL, 1),
(3637545, 506387, 67301, '<td valign="top">I am not quite sure what you have done to accomplish this look but it is quite extraordinary. You may have added rain or perhaps a motion blur layer. The crop is also unusual. I think that if this is what you intended and you are happy with it then that is great. For me it all seems to be a bit confusing and cluttered. I find the contrast a little insensitive too. I would be very interested to know your inspiration for the shot.</td>', 'I am not quite sure what you have done to accomplish this look but it is quite extraordinary. You may have added rain or perhaps a motion blur layer. The crop is also unusual. I think that if this is what you intended and you are happy with it then that is great. For me it all seems to be a bit confusing and cluttered. I find the contrast a little insensitive too. I would be very interested to know your inspiration for the shot.', '2007-05-10 16:39:36.000000', NULL, 1),
(3637566, 506222, 67301, '<td valign="top">Very dark visually and title. The over enhancement has given a lot of speckle and although it is easy to see the mushrooms the overall look is not pleasing to MY eye. Sorry</td>', 'Very dark visually and title. The over enhancement has given a lot of speckle and although it is easy to see the mushrooms the overall look is not pleasing to MY eye. Sorry', '2007-05-10 16:51:05.000000', NULL, 1),
(3637640, 507312, 67301, '<td valign="top">A faster shutter speed would help freeze movement and give a sharper image. If you have an editor use a sharp mask and adjust contrast to make the colours pop a little. I think your title is a little sad and if you really feel that your scores are low may I suggest that you get a full review from the critique club</td>', 'A faster shutter speed would help freeze movement and give a sharper image. If you have an editor use a sharp mask and adjust contrast to make the colours pop a little. I think your title is a little sad and if you really feel that your scores are low may I suggest that you get a full review from the critique club', '2007-05-10 17:11:49.000000', NULL, 1),
(3637735, 507956, 27839, '<td valign="top">Very Cute and I love the way the photo brings out the blue in her eyes.</td>', 'Very Cute and I love the way the photo brings out the blue in her eyes.', '2007-05-10 17:56:41.000000', NULL, 1),
