(3640194, 507071, 46314, '<td valign="top">Why is the ham green?</td>', 'Why is the ham green?', '2007-05-11 17:23:02.000000', NULL, 1),
(3640196, 507241, 46314, '<td valign="top">Very nice photo. Well composed, lit and edited.</td>', 'Very nice photo. Well composed, lit and edited.', '2007-05-11 17:23:31.000000', NULL, 1),
(3640198, 508026, 46314, '<td valign="top">Very interesting set up. Nicely taken, although the dark shadows on the one side seems to put it a bit off balance.</td>', 'Very interesting set up. Nicely taken, although the dark shadows on the one side seems to put it a bit off balance.', '2007-05-11 17:24:25.000000', NULL, 1),
(3640200, 507472, 46314, '<td valign="top">Interesting way to convey your message.</td>', 'Interesting way to convey your message.', '2007-05-11 17:25:01.000000', NULL, 1),
(3640201, 507640, 46314, '<td valign="top">Funny looking dog.</td>', 'Funny looking dog.', '2007-05-11 17:25:43.000000', NULL, 1),
(3640203, 507956, 46314, '<td valign="top">Nicely taken photo.</td>', 'Nicely taken photo.', '2007-05-11 17:26:04.000000', NULL, 1),
(3640205, 507718, 46314, '<td valign="top">Nicely composed and edited.</td>', 'Nicely composed and edited.', '2007-05-11 17:26:29.000000', NULL, 1),
