(3640210, 508073, 46314, '<td valign="top">On it''s way to a microstock site. Need to keep that white background a bit whiter though.</td>', 'On it''s way to a microstock site. Need to keep that white background a bit whiter though.', '2007-05-11 17:27:42.000000', NULL, 1),
(3640214, 507270, 46314, '<td valign="top">Interesting idea. Comes off a bit messy in the execution though.</td>', 'Interesting idea. Comes off a bit messy in the execution though.', '2007-05-11 17:29:04.000000', NULL, 1),
(3640216, 507906, 46314, '<td valign="top">Lighting isn''t very good. Needed far more diffuse lighting to get rid of those harsh shadows. (Try tracing paper in front of your flash). I like the idea though.</td>', 'Lighting isn''t very good. Needed far more diffuse lighting to get rid of those harsh shadows. (Try tracing paper in front of your flash). I like the idea though.', '2007-05-11 17:30:16.000000', NULL, 1),
(3640217, 508046, 46314, '<td valign="top">Very interesting subject. I like the colour palette in the photo. Good focus and sharpness.</td>', 'Very interesting subject. I like the colour palette in the photo. Good focus and sharpness.', '2007-05-11 17:31:01.000000', NULL, 1),
(3640219, 506633, 46314, '<td valign="top">Pity that daisy didn''t have more life in it. But a nice photo nevertheless.</td>', 'Pity that daisy didn''t have more life in it. But a nice photo nevertheless.', '2007-05-11 17:31:35.000000', NULL, 1),
(3640220, 508133, 46314, '<td valign="top">You have some interesting little friends...</td>', 'You have some interesting little friends...', '2007-05-11 17:32:08.000000', NULL, 1),
(3640222, 506960, 46314, '<td valign="top">Interesting idea.</td>', 'Interesting idea.', '2007-05-11 17:32:44.000000', NULL, 1),
(3640224, 508087, 46314, '<td valign="top">I think if you''d left out the phone subject, the boy with the kite alone would have made for a stronger image.</td>', 'I think if you''d left out the phone subject, the boy with the kite alone would have made for a stronger image.', '2007-05-11 17:33:58.000000', NULL, 1),
(3640226, 508119, 46314, '<td valign="top">Nice horses.</td>', 'Nice horses.', '2007-05-11 17:34:32.000000', NULL, 1),
(3640227, 508120, 46314, '<td valign="top">I like the strong geometrics and bold colours, but somehow the composition seems a bit off, and I don''t think it holds enough interest.</td>', 'I like the strong geometrics and bold colours, but somehow the composition seems a bit off, and I don''t think it holds enough interest.', '2007-05-11 17:35:37.000000', NULL, 1),
(3640230, 507369, 46314, '<td valign="top">Clever idea. Decent execution, although a simpler background would have made for a stronger image.</td>', 'Clever idea. Decent execution, although a simpler background would have made for a stronger image.', '2007-05-11 17:36:16.000000', NULL, 1),
(3640232, 508091, 46314, '<td valign="top">Nice subjects. Good use of framing.</td>', 'Nice subjects. Good use of framing.', '2007-05-11 17:36:50.000000', NULL, 1),
(3640234, 507215, 46314, '<td valign="top">Cool turtles. Weird texture in the photo. Sharpening process? Nice image though.</td>', 'Cool turtles. Weird texture in the photo. Sharpening process? Nice image though.', '2007-05-11 17:37:55.000000', NULL, 1),
(3640236, 508117, 46314, '<td valign="top">Nice green eggs and ham.</td>', 'Nice green eggs and ham.', '2007-05-11 17:38:48.000000', NULL, 1),
(3640237, 508040, 46314, '<td valign="top">Clever set up. Focus and DOF are a bit off though.</td>', 'Clever set up. Focus and DOF are a bit off though.', '2007-05-11 17:39:23.000000', NULL, 1),
(3640238, 507809, 46314, '<td valign="top">That captures my mood EVERY morning. Nicely taken.</td>', 'That captures my mood EVERY morning. Nicely taken.', '2007-05-11 17:40:19.000000', NULL, 1),
(3640240, 507237, 46314, '<td valign="top">Nice props and make-up.</td>', 'Nice props and make-up.', '2007-05-11 17:40:59.000000', NULL, 1),
(3640246, 508074, 46314, '<td valign="top">Nice shot. You seem to have a real knack for food/table photography. If it weren''t for the green eggs and ham, this photo would do well in any lifestyle magazine.</td>', 'Nice shot. You seem to have a real knack for food/table photography. If it weren''t for the green eggs and ham, this photo would do well in any lifestyle magazine.', '2007-05-11 17:42:23.000000', NULL, 1),
(3640255, 507723, 46314, '<td valign="top">Not a badly taken photo, but not a terribly creative one either.</td>', 'Not a badly taken photo, but not a terribly creative one either.', '2007-05-11 17:44:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3640258, 507198, 46314, '<td valign="top">Pity not all of the fish were sharp. Did you use a flash? That might have helped you bump up the shutter speed to avoid the motion blur. Check out underwater/fishtank flash techniques on a site called www.strobist.com</td>', 'Pity not all of the fish were sharp. Did you use a flash? That might have helped you bump up the shutter speed to avoid the motion blur. Check out underwater/fishtank flash techniques on a site called www.strobist.com', '2007-05-11 17:46:37.000000', NULL, 1),
(3640259, 507681, 46314, '<td valign="top">Nicely taken.</td>', 'Nicely taken.', '2007-05-11 17:47:08.000000', NULL, 1),
(3640263, 508148, 46314, '<td valign="top">Cleverly done on the selective colour.</td>', 'Cleverly done on the selective colour.', '2007-05-11 17:47:47.000000', NULL, 1),
(3640264, 507909, 46314, '<td valign="top">Nice use of bold colours. Decent composition too.</td>', 'Nice use of bold colours. Decent composition too.', '2007-05-11 17:48:22.000000', NULL, 1),
(3640267, 508149, 46314, '<td valign="top">Great photo. The central composition actually works well with the goats posed. Nice focus/DOF and colour.</td>', 'Great photo. The central composition actually works well with the goats posed. Nice focus/DOF and colour.', '2007-05-11 17:49:03.000000', NULL, 1),
(3640269, 508098, 46314, '<td valign="top">Nicely taken. I like the simple composition and bold colours.</td>', 'Nicely taken. I like the simple composition and bold colours.', '2007-05-11 17:49:33.000000', NULL, 1),
(3640270, 507149, 46314, '<td valign="top">Very funny looking monkey.</td>', 'Very funny looking monkey.', '2007-05-11 17:50:00.000000', NULL, 1),
(3640271, 508025, 46314, '<td valign="top">Nicely taken shot.</td>', 'Nicely taken shot.', '2007-05-11 17:50:23.000000', NULL, 1),
(3640273, 508078, 46314, '<td valign="top">Very funny photo. Cleverly done.</td>', 'Very funny photo. Cleverly done.', '2007-05-11 17:50:46.000000', NULL, 1),
(3640276, 507911, 46314, '<td valign="top">Nice shot, seen it done better though.</td>', 'Nice shot, seen it done better though.', '2007-05-11 17:51:39.000000', NULL, 1),
(3640279, 508059, 46314, '<td valign="top">Nice use of lines for a repetitive pattern, and nice bold colours, but overall not a very good photo. Maybe needed to play around with the perspective a bit more (either flat perspective to get straight lines, or wider angle to warp the lines for more interest?)</td>', 'Nice use of lines for a repetitive pattern, and nice bold colours, but overall not a very good photo. Maybe needed to play around with the perspective a bit more (either flat perspective to get straight lines, or wider angle to warp the lines for more interest?)', '2007-05-11 17:53:05.000000', NULL, 1),
(3640282, 505552, 46314, '<td valign="top">Nice shot, but red hat and b&amp;w cat would just have nailed Seuss so much better.</td>', 'Nice shot, but red hat and b&w cat would just have nailed Seuss so much better.', '2007-05-11 17:53:50.000000', NULL, 1),
(3640285, 508050, 46314, '<td valign="top">Cropping is a bit tight. Hands/hair seem chopped up a bit.</td>', 'Cropping is a bit tight. Hands/hair seem chopped up a bit.', '2007-05-11 17:54:45.000000', NULL, 1),
(3640286, 507850, 46314, '<td valign="top">Nice duck shot.</td>', 'Nice duck shot.', '2007-05-11 17:55:09.000000', NULL, 1),
(3640287, 506742, 46314, '<td valign="top">Great shot of Stonehenge, but not very Dr. Seuss...</td>', 'Great shot of Stonehenge, but not very Dr. Seuss...', '2007-05-11 17:55:42.000000', NULL, 1),
(3640289, 508064, 46314, '<td valign="top">Doesn''t seem as sharp/focussed as it could be.</td>', 'Doesn''t seem as sharp/focussed as it could be.', '2007-05-11 17:56:19.000000', NULL, 1),
(3640291, 507407, 46314, '<td valign="top">Great Dr. Seuss shot. Nice colour and lighting, and the setup/compostion have a zany Seuss feel. Well done.</td>', 'Great Dr. Seuss shot. Nice colour and lighting, and the setup/compostion have a zany Seuss feel. Well done.', '2007-05-11 17:57:07.000000', NULL, 1),
(3640293, 506301, 46314, '<td valign="top">Funny.</td>', 'Funny.', '2007-05-11 17:57:26.000000', NULL, 1),
(3640296, 506049, 46314, '<td valign="top">Image doesn''t really bring out the subject well, and you seem to have a purple-fringing (chromatic aberration) problem with your camera.</td>', 'Image doesn''t really bring out the subject well, and you seem to have a purple-fringing (chromatic aberration) problem with your camera.', '2007-05-11 17:58:18.000000', NULL, 1),
(3640298, 508121, 46314, '<td valign="top">Nice idea - makes for a simple but strong image. A little off-focus/lack of sharpness.</td>', 'Nice idea - makes for a simple but strong image. A little off-focus/lack of sharpness.', '2007-05-11 17:59:10.000000', NULL, 1),
(3640300, 507981, 46314, '<td valign="top">Lovely iguana. Well shot - nice sharpness. Really brings out the detail on those scales. Not very Seuss though.</td>', 'Lovely iguana. Well shot - nice sharpness. Really brings out the detail on those scales. Not very Seuss though.', '2007-05-11 17:59:53.000000', NULL, 1),
(3640302, 507980, 46314, '<td valign="top">Not a very interesting image, and seems a bit tightly cropped.</td>', 'Not a very interesting image, and seems a bit tightly cropped.', '2007-05-11 18:00:15.000000', NULL, 1),
(3640305, 507762, 46314, '<td valign="top">a great photo. Very good composition - makes for a strong image. Pose/expression is just perfect. A pity you didn''t selectively colour the hat red/white - that would have made it my winner for this challenge.</td>', 'a great photo. Very good composition - makes for a strong image. Pose/expression is just perfect. A pity you didn''t selectively colour the hat red/white - that would have made it my winner for this challenge.', '2007-05-11 18:02:07.000000', NULL, 1),
(3640307, 507842, 46314, '<td valign="top">Nice use of selective colour. When you see the palms like that, they actually do look like something out of a Seuss book.</td>', 'Nice use of selective colour. When you see the palms like that, they actually do look like something out of a Seuss book.', '2007-05-11 18:02:50.000000', NULL, 1),
(3640310, 506551, 46314, '<td valign="top">Nice meerkat.</td>', 'Nice meerkat.', '2007-05-11 18:03:31.000000', NULL, 1),
(3640316, 507840, 46314, '<td valign="top">Interesting concept. I think you should keep playing around with this concept - there is a gem of a photo lurking somewhere close.This one hasn''t quite nailed it yet though.</td>', 'Interesting concept. I think you should keep playing around with this concept - there is a gem of a photo lurking somewhere close.This one hasn''t quite nailed it yet though.', '2007-05-11 18:04:59.000000', NULL, 1),
(3640319, 508095, 46314, '<td valign="top">Funny. Nicely constructed hat (a late-night entry, perhaps?)</td>', 'Funny. Nicely constructed hat (a late-night entry, perhaps?)', '2007-05-11 18:05:42.000000', NULL, 1),
(3640323, 508043, 46314, '<td valign="top">Nice image. Very interesting colour palette.</td>', 'Nice image. Very interesting colour palette.', '2007-05-11 18:06:14.000000', NULL, 1),
(3640325, 508072, 46314, '<td valign="top">Nice shot. Not very Seuss, but interesting use of the title.</td>', 'Nice shot. Not very Seuss, but interesting use of the title.', '2007-05-11 18:06:52.000000', NULL, 1),
(3640476, 508043, 78114, '<td valign="top">beautiful color! a lovely shot.</td>', 'beautiful color! a lovely shot.', '2007-05-11 19:20:36.000000', NULL, 1),
(3640507, 508146, 39381, '<td valign="top">Nice. My choice for the blue ribbon.</td>', 'Nice. My choice for the blue ribbon.', '2007-05-11 19:31:11.000000', NULL, 1),
(3640510, 507407, 39381, '<td valign="top">Very Good work all-around. I''m thinking this will "ribbon".</td>', 'Very Good work all-around. I''m thinking this will "ribbon".', '2007-05-11 19:32:26.000000', NULL, 1),
(3640524, 508073, 25616, '<td valign="top">to the point!!</td>', 'to the point!!', '2007-05-11 19:40:21.000000', NULL, 1),
(3640527, 508095, 25616, '<td valign="top">cool</td>', 'cool', '2007-05-11 19:42:48.000000', NULL, 1),
(3640544, 507920, 55838, '<td valign="top">Fabulous.  Top two in my estimation.  Great idea and awesome colors.  Feels kind of like a dream.  Back to bump you up to 9.</td>', 'Fabulous.  Top two in my estimation.  Great idea and awesome colors.  Feels kind of like a dream.  Back to bump you up to 9.', '2007-05-11 19:53:14.000000', NULL, 1),
(3640552, 506742, 55838, '<td valign="top">Stunning.  Beautifully processed.  Blue or Red IMO.  Back to bump you up to 9.</td>', 'Stunning.  Beautifully processed.  Blue or Red IMO.  Back to bump you up to 9.', '2007-05-11 19:54:49.000000', NULL, 1),
(3640558, 506633, 55838, '<td valign="top">Fun shot with cool vivid color.  Very cute little model too!  Feels ever-so-slightly off center but lovely none the less.  Back to bump you up to 8.</td>', 'Fun shot with cool vivid color.  Very cute little model too!  Feels ever-so-slightly off center but lovely none the less.  Back to bump you up to 8.', '2007-05-11 19:57:32.000000', NULL, 1),
(3640560, 508146, 55838, '<td valign="top">Nice clean colors and a fun set up.  Back to bump you up to 8.</td>', 'Nice clean colors and a fun set up.  Back to bump you up to 8.', '2007-05-11 19:58:41.000000', NULL, 1),
(3640571, 507909, 55838, '<td valign="top">One of my favorites of the challenge.  Perfect storytelling and really captures the Seuss feel.  So cute - makes me smile.  Back to bump you up to 9 and adding to favorites.</td>', 'One of my favorites of the challenge.  Perfect storytelling and really captures the Seuss feel.  So cute - makes me smile.  Back to bump you up to 9 and adding to favorites.', '2007-05-11 20:03:19.000000', NULL, 1),
(3640576, 507911, 55838, '<td valign="top">Back to bump you up to 8.   Nice clean image.</td>', 'Back to bump you up to 8.   Nice clean image.', '2007-05-11 20:05:04.000000', NULL, 1),
(3640581, 508087, 55838, '<td valign="top">Pleasantly peculiar.  Very entertaining set up and a great mood.  Odd colors but that''s Seuss for ya!  Back to bump you up to 8.</td>', 'Pleasantly peculiar.  Very entertaining set up and a great mood.  Odd colors but that''s Seuss for ya!  Back to bump you up to 8.', '2007-05-11 20:06:57.000000', NULL, 1),
(3640586, 507369, 55838, '<td valign="top">What a fantastically real and fun shot!  I adore the kids faces and you guys obviously had a great time with this one.  That''s what it''s all about after all!  Maybe not a technically perfect image but it sure makes my smile and feel that warm family feeling!  Back to bump you up to 8.</td>', 'What a fantastically real and fun shot!  I adore the kids faces and you guys obviously had a great time with this one.  That''s what it''s all about after all!  Maybe not a technically perfect image but it sure makes my smile and feel that warm family feeling!  Back to bump you up to 8.', '2007-05-11 20:09:05.000000', NULL, 1),
(3640589, 508043, 55838, '<td valign="top">I''m so glad to see all the references to the LORAX in this challenge as it is my very favoritest Seuss book of all!  I really like to the DOF and these are surely Truffula''s!  Back to bump you up to 8.</td>', 'I''m so glad to see all the references to the LORAX in this challenge as it is my very favoritest Seuss book of all!  I really like to the DOF and these are surely Truffula''s!  Back to bump you up to 8.', '2007-05-11 20:10:56.000000', NULL, 1),
(3640723, 508059, 35602, '<td valign="top">Great detail, but not the most creative.</td>', 'Great detail, but not the most creative.', '2007-05-11 21:35:14.000000', NULL, 1),
(3640725, 506551, 35602, '<td valign="top">Seems very grainy and maybe oversharpened.  The exposure was probably not well set when the pic was taken.  Maybe iso was too high as well.</td>', 'Seems very grainy and maybe oversharpened.  The exposure was probably not well set when the pic was taken.  Maybe iso was too high as well.', '2007-05-11 21:37:31.000000', NULL, 1),
(3640728, 507312, 35602, '<td valign="top">Yep, that is probably right.</td>', 'Yep, that is probably right.', '2007-05-11 21:38:49.000000', NULL, 1),
(3640732, 507840, 35602, '<td valign="top">Too much uneven light.  Makes everything glary.</td>', 'Too much uneven light.  Makes everything glary.', '2007-05-11 21:44:03.000000', NULL, 1),
(3640734, 507151, 35602, '<td valign="top">Not the most interesting shot.</td>', 'Not the most interesting shot.', '2007-05-11 21:44:28.000000', NULL, 1),
(3640736, 506550, 35602, '<td valign="top">A bit oof and exposure could be better</td>', 'A bit oof and exposure could be better', '2007-05-11 21:44:36.000000', NULL, 1),
